begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values('07000000-0000-4000-8000-000000000001','capacity-admin@example.test',now()),('07000000-0000-4000-8000-000000000002','capacity-member@example.test',now());
insert into auth.sessions(id,user_id,created_at,updated_at) values('17000000-0000-4000-8000-000000000001','07000000-0000-4000-8000-000000000001',now(),now()),('17000000-0000-4000-8000-000000000002','07000000-0000-4000-8000-000000000002',now(),now());
insert into profiles(id,username,display_name,role,policy_version,policy_accepted_at)values('07000000-0000-4000-8000-000000000001','capacity_admin','Admin','admin','2026-11-01',now()),('07000000-0000-4000-8000-000000000002','capacity_member','Member','member','2026-11-01',now());
update workspace_settings set limits=limits||'{"members":4,"admins":2,"open_invites":2,"file_bytes":10,"html_bytes":10,"total_bytes":110,"member_bytes":50,"classes":2,"lessons_per_class":2,"notes_per_class":2,"quizzes_per_class":2,"questions_per_quiz":2,"lesson_bytes":10,"note_bytes":20,"files_per_folder":2,"saved_files":2,"pending_submissions":2}'::jsonb;
select lives_ok($$select reserve_invitation('07000000-0000-4000-8000-000000000001','capacity-invite-a@example.test','admin')$$,'admin invitation can fill final admin seat');
select throws_ok($$select reserve_invitation('07000000-0000-4000-8000-000000000001','capacity-invite-b@example.test','admin')$$,'23514',null,'next invited admin is blocked');
select lives_ok($$select reserve_invitation('07000000-0000-4000-8000-000000000001','capacity-invite-b@example.test','member')$$,'open invitation reaches limit');
select throws_ok($$select reserve_invitation('07000000-0000-4000-8000-000000000001','capacity-invite-c@example.test','member')$$,'23514',null,'next open invitation is blocked');
select is((select max(expires_at) from invitations),now()+interval '7 days','reservation expiry follows invite_days setting');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"07000000-0000-4000-8000-000000000002","session_id":"17000000-0000-4000-8000-000000000002","aal":"aal1"}',true);
reset role;
insert into classes(id,name,created_by)values('27000000-0000-4000-8000-000000000001','Capacity A',auth.uid()),('27000000-0000-4000-8000-000000000002','Capacity B',auth.uid());
set local role authenticated;
select throws_ok($$insert into classes(name,created_by)values('Too many',auth.uid())$$,'23514',null,'class limit plus one is blocked');
insert into lessons(class_id,title,markdown,created_by)values('27000000-0000-4000-8000-000000000001','A','a',auth.uid());
select lives_ok($$update lessons set markdown=repeat('x',9)$$,'lesson accepts byte limit minus one');
select lives_ok($$update lessons set markdown=repeat('x',10)$$,'lesson accepts exact byte limit');
select throws_ok($$update lessons set markdown=repeat('x',11)$$,'23514',null,'lesson rejects byte limit plus one');
select lives_ok($$insert into lessons(class_id,title,markdown,created_by)values('27000000-0000-4000-8000-000000000001','B','b',auth.uid())$$,'second lesson reaches class lesson limit');
select throws_ok($$insert into lessons(class_id,title,markdown,created_by)values('27000000-0000-4000-8000-000000000001','C','c',auth.uid())$$,'23514',null,'next lesson is blocked');
insert into notes(class_id,title,body,created_by)values('27000000-0000-4000-8000-000000000001','A','a',auth.uid());
select lives_ok($$update notes set body=repeat('x',17)$$,'note accepts combined byte limit minus one');
select lives_ok($$update notes set body=repeat('x',18)$$,'note accepts combined byte limit');
select throws_ok($$update notes set body=repeat('x',19)$$,'23514',null,'note rejects combined byte limit plus one');
select lives_ok($$insert into notes(class_id,title,body,created_by)values('27000000-0000-4000-8000-000000000001','B','b',auth.uid())$$,'second note reaches class note limit');
select throws_ok($$insert into notes(class_id,title,body,created_by)values('27000000-0000-4000-8000-000000000001','C','c',auth.uid())$$,'23514',null,'next note is blocked');
select create_folder('Capacity uploads');
select lives_ok($$select request_upload('first.txt',9,'text/plain',(select id from folders limit 1))$$,'first file is below folder capacity');
select lives_ok($$select request_upload('second.txt',10,'text/plain',(select id from folders limit 1))$$,'second file reaches folder capacity');
select throws_ok($$select request_upload('third.txt',1,'text/plain',(select id from folders limit 1))$$,'23514',null,'next file in full folder is blocked');
select lives_ok($$select request_upload('first.html',9,'text/html',null,'html_quiz')$$,'HTML accepts size limit minus one');
select lives_ok($$select request_upload('second.html',10,'text/html',null,'html_quiz')$$,'HTML accepts size limit');
select throws_ok($$select request_upload('large.html',11,'text/html',null,'html_quiz')$$,'23514',null,'HTML rejects size limit plus one');
select request_upload('root.txt',10,'text/plain');select request_upload('small.txt',2,'text/plain');
select throws_ok($$select request_upload('over.html',1,'text/html',null,'html_quiz')$$,'23514',null,'member quota includes HTML and pending files');
select set_config('request.jwt.claims','{"sub":"07000000-0000-4000-8000-000000000001","session_id":"17000000-0000-4000-8000-000000000001","aal":"aal1"}',true);
select request_upload('admin-'||i||'.html',10,'text/html',null,'html_quiz') from generate_series(1,5)i;
select lives_ok($$select request_upload('admin-last.html',9,'text/html',null,'html_quiz')$$,'admin is exempt from personal quota and total reaches limit minus one');
select lives_ok($$select request_upload('admin-final.html',1,'text/html',null,'html_quiz')$$,'total reservation reaches exact limit');
select throws_ok($$select request_upload('admin-over.html',1,'text/html',null,'html_quiz')$$,'23514',null,'total storage limit blocks next byte even for admin');
reset role;
update files set state='ready',ready_at=now() where purpose='vault';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"07000000-0000-4000-8000-000000000002","session_id":"17000000-0000-4000-8000-000000000002","aal":"aal1"}',true);
select lives_ok($$insert into saved_files(user_id,file_id)select auth.uid(),id from files where name='first.txt'$$,'saved files accepts limit minus one');
select lives_ok($$insert into saved_files(user_id,file_id)select auth.uid(),id from files where name='second.txt'$$,'saved files accepts exact limit');
select throws_ok($$insert into saved_files(user_id,file_id)select auth.uid(),id from files where name='root.txt'$$,'23514',null,'saved files blocks next bookmark');
create temporary table qfixture(content jsonb,settings jsonb);
insert into qfixture values('{"format_version":1,"questions":[{"id":"q1","type":"true_false","prompt":"A?","points":1,"answer":true}]}','{"shuffle":false,"mode":"paged","page_size":10,"quiz_seconds":null,"question_seconds":null}');
select lives_ok($$select save_quiz('27000000-0000-4000-8000-000000000001','Q1','manual',(select content from qfixture),(select settings from qfixture))$$,'quiz question count accepts limit minus one');
update qfixture set content=jsonb_set(content,'{questions}',content->'questions'||jsonb_build_array(jsonb_set(content#>'{questions,0}','{id}','"q2"')));
select lives_ok($$select save_quiz('27000000-0000-4000-8000-000000000001','Q2','manual',(select content from qfixture),(select settings from qfixture))$$,'question count and class quiz count reach limits');
select throws_ok($$select save_quiz('27000000-0000-4000-8000-000000000001','Q3','manual',(select content from qfixture),(select settings from qfixture))$$,'23514',null,'class quiz count blocks next quiz');
update qfixture set content=jsonb_set(content,'{questions}',content->'questions'||jsonb_build_array(jsonb_set(content#>'{questions,0}','{id}','"q3"')));
select throws_ok($$select save_quiz('27000000-0000-4000-8000-000000000002','Too many questions','manual',(select content from qfixture),(select settings from qfixture))$$,'23514',null,'question count blocks limit plus one');
update qfixture set content=jsonb_set(content,'{questions}',jsonb_build_array(content#>'{questions,0}'));
select save_quiz('27000000-0000-4000-8000-000000000002','Q3','manual',(select content from qfixture),(select settings from qfixture));
select lives_ok($$select submit_quiz((select v.id from quiz_versions v join quizzes q on q.id=v.quiz_id where q.title='Q1'))$$,'pending count accepts limit minus one');
select lives_ok($$select submit_quiz((select v.id from quiz_versions v join quizzes q on q.id=v.quiz_id where q.title='Q2'))$$,'pending count reaches limit');
select throws_ok($$select submit_quiz((select v.id from quiz_versions v join quizzes q on q.id=v.quiz_id where q.title='Q3'))$$,'23514',null,'pending count blocks next submission');
reset role;
select throws_ok($$select update_settings('07000000-0000-4000-8000-000000000001','CQStudio','2026-11-01',(select limits||'{"questions_per_quiz":1}' from workspace_settings))$$,'23514',null,'settings cannot shrink below current question usage');
select throws_ok($$update workspace_settings set limits=limits||'{"chat_days":30}'$$,'23514',null,'retention changes require a new policy version');
select is((select count(*) from classes),2::bigint,'reached capacities preserve existing classes');
select is((select count(*) from files),13::bigint,'reached storage capacity preserves reservations');
select * from finish();
rollback;
